import { useQuery, UseQueryResult } from '@tanstack/react-query';

export type Todo = { id: number; title: string; done: boolean };

export const todoKeys = {
  all: () => ['todos'] as const,
  lists: () => [...todoKeys.all(), 'list'] as const,
  detail: (id: number) => [...todoKeys.all(), 'detail', id] as const,
};

export type TodoKeys = {
  all: ReturnType<typeof todoKeys.all>;
  lists: ReturnType<typeof todoKeys.lists>;
  detail: ReturnType<typeof todoKeys.detail>;
};

export async function fetchTodos(): Promise<Todo[]> {
  const r = await fetch('/api/todos');
  return r.json() as Promise<Todo[]>;
}

export function useTodos(): UseQueryResult<Todo[]> {
  return useQuery({
    queryKey: todoKeys.lists(),
    queryFn: fetchTodos,
  });
}
